#include <iostream>
#include <iomanip>
#include <cstddef>
#include <stdexcept>

class Array {
private:
    std::size_t size_{0};
    int* ptr_{nullptr};

public:
    // Default constructor zero-initializes the dynamic array
    explicit Array(std::size_t sz = 4) 
        : size_{sz}, ptr_{sz > 0 ? new int[sz]{} : nullptr} {}

    ~Array() {
        delete[] ptr_;
    }

    std::size_t getSize() const { return size_; }

    // Subscript operator for non-const objects (returns lvalue reference)
    int& operator[](int subscript) {
        if (subscript < 0 || static_cast<std::size_t>(subscript) >= size_) {
            throw std::out_of_range("Subscript out of range");
        }
        return ptr_[subscript];
    }

    // Overloaded subscript operator for const Arrays (page 744: returns rvalue copy)
    int operator[](int subscript) const {
        if (subscript < 0 || static_cast<std::size_t>(subscript) >= size_) {
            throw std::out_of_range("Subscript out of range");
        }
        return ptr_[subscript]; // copy return creates an rvalue
    }

    // Overloaded stream extraction operator (friend)
    friend std::istream& operator>>(std::istream& in, Array& a) {
        // Range-based for cannot iterate raw dynamic pointer ptr_
        for (std::size_t i = 0; i < a.size_; ++i) {
            in >> a.ptr_[i];
        }
        return in;
    }

    // Overloaded stream insertion operator (friend)
    friend std::ostream& operator<<(std::ostream& out, const Array& a) {
        for (std::size_t i = 0; i < a.size_; ++i) {
            out << std::setw(6) << a.ptr_[i];
            if ((i + 1) % 4 == 0) out << "\n";
        }
        if (a.size_ % 4 != 0) out << "\n";
        return out;
    }
};

int main() {
    Array arr(4);
    std::cin >> arr;

    const Array& constRef = arr;
    std::cout << "Const read arr[2]: " << constRef[2] << "\n";

    std::cout << "Full array:\n" << arr;
    return 0;
}

#include <iostream>
#include <cstddef>

class SafeIntArray {
private:
    std::size_t size_{0};
    int* ptr_{nullptr};

public:
    // Default constructor zero-initializes elements
    explicit SafeIntArray(std::size_t sz = 3)
        : size_{sz}, ptr_{sz > 0 ? new int[sz]{} : nullptr} {}

    // Copy constructor (Software Engineering Observation 18.3: const reference argument)
    SafeIntArray(const SafeIntArray& other)
        : size_{other.size_}, ptr_{other.size_ > 0 ? new int[other.size_] : nullptr} {
        for (std::size_t i = 0; i < size_; ++i) {
            ptr_[i] = other.ptr_[i]; // Deep copy
        }
    }

    ~SafeIntArray() {
        delete[] ptr_;
        // ptr_ ceases to exist here, but helper deallocation functions must set nullptr
    }

    // Helper demonstrating Error-Prevention Tip 18.3
    void resetBuffer(std::size_t newSz) {
        delete[] ptr_;
        ptr_ = nullptr; // Tip 18.3: prevent dangling pointer if subsequent new throws
        size_ = newSz;
        ptr_ = (newSz > 0) ? new int[newSz]{} : nullptr;
    }

    void set(std::size_t i, int val) { if (i < size_) ptr_[i] = val; }
    int get(std::size_t i) const { return ptr_[i]; }
    std::size_t getSize() const { return size_; }
};

int main() {
    SafeIntArray a1(2);
    a1.set(0, 111);
    a1.set(1, 222);

    // Deep copy invoked
    SafeIntArray a2 = a1;
    a2.set(0, 999); // Does not affect a1

    std::cout << "a1[0]: " << a1.get(0) << "\n";
    std::cout << "a2[0]: " << a2.get(0) << "\n";

    // Demonstrate safe reset
    a2.resetBuffer(1);
    a2.set(0, 555);
    std::cout << "a2 reset size: " << a2.getSize() << ", val: " << a2.get(0) << "\n";
    return 0;
}

#include <iostream>
#include <utility>
#include <cstddef>

class Array {
private:
    std::size_t size_{0};
    int* ptr_{nullptr};

public:
    explicit Array(std::size_t sz = 2)
        : size_{sz}, ptr_{sz > 0 ? new int[sz]{} : nullptr} {}

    // Copy constructor (Deep Copy)
    Array(const Array& right)
        : size_{right.size_}, ptr_{right.size_ > 0 ? new int[right.size_] : nullptr} {
        for (std::size_t i = 0; i < size_; ++i) {
            ptr_[i] = right.ptr_[i];
        }
    }

    // C++11 Move constructor (page 747: move semantics transfers ownership)
    Array(Array&& right) noexcept 
        : size_{right.size_}, ptr_{right.ptr_} {
        right.size_ = 0;
        right.ptr_ = nullptr;
    }

    ~Array() {
        delete[] ptr_;
    }

    // Overloaded assignment operator with self-assignment protection
    const Array& operator=(const Array& right) {
        if (this != &right) { // Prevent self-assignment
            if (size_ != right.size_) {
                delete[] ptr_;
                size_ = right.size_;
                ptr_ = new int[size_];
            }
            for (std::size_t i = 0; i < size_; ++i) {
                ptr_[i] = right.ptr_[i];
            }
        }
        return *this; // Enables x = y = z
    }

    // Overloaded equality operator
    bool operator==(const Array& right) const {
        if (size_ != right.size_) return false;
        for (std::size_t i = 0; i < size_; ++i) {
            if (ptr_[i] != right.ptr_[i]) return false;
        }
        return true;
    }

    // Overloaded inequality operator delegates to operator==
    bool operator!=(const Array& right) const {
        return !(*this == right);
    }

    void set(std::size_t i, int v) { ptr_[i] = v; }
    int get(std::size_t i) const { return ptr_[i]; }
};

int main() {
    Array a1(2);
    a1.set(0, 10);
    a1.set(1, 20);

    Array a2(2);
    a2 = a1; // Copy assignment
    a2 = a2; // Self-assignment safe

    std::cout << "a1 == a2: " << std::boolalpha << (a1 == a2) << "\n";

    a2.set(1, 99);
    std::cout << "After modification, a1 != a2: " << (a1 != a2) << "\n";

    // C++11 Move constructor invocation
    Array a3 = std::move(a2);
    std::cout << "a3[0]: " << a3.get(0) << ", a3[1]: " << a3.get(1) << "\n";
    return 0;
}
